local ADDON_NAME, ns = ...
-- Goblin Ledger: craft and smelt profit.
--
-- What buying the mats, making an item (or smelting a bar) and selling it on
-- the auction house brings, from the same prices as the rest of the addon:
--   - a recipe item's tooltip (Plans, Pattern, Formula, Schematic, Recipe,
--     Manual), for everyone: what it makes and sells for, the mats with their
--     cost, and the profit (a bind-on-pickup item: the mats only);
--   - a crafted item's tooltip, when you know (or may know) its recipe: the
--     mats and the profit;
--   - a mat's tooltip (ore, bars, stone ...), when you have the profession: the
--     best recipe you know that uses it ("Smelt to Thorium Bar"). Smelting is
--     Mining, so a blacksmith without Mining sees nothing on ore;
--   - the Professions window: one line by the Create button for the recipe
--     you picked;
--   - the auction house sidebar: one flip idea from your own recipes;
--   - an empty auction house search for a recipe item, or for something you
--     can make: what it makes and its mats with their cost, under the AH
--     code's own lines (ns.EmptySearchLines; they say whether it is listed);
--     for a bind-on-pickup item you cannot make, the plans that make it.
-- Prices: the mats at the cheapest listing (the live one while the auction
-- house shows it, not your own, or a vendor's when that is cheaper), the item
-- at the price its own tooltip says to sell at (Recommend.lua's ns.SellAt:
-- Sell now, 1c under the cheapest listing, the live one while the auction
-- house shows it, yours matched; or the usual price when Sell now is under 70%
-- of it), after the 5% cut, times the average number one craft makes. A profit is only claimed (green) when it
-- is more than 10% of the mats at the cheapest prices (the item at that price),
-- at AH value (the item at most 25% over what it sold for in the last day) and
-- at the 7-day averages (the smallest of the three is the one shown), and the made
-- item has 3 or more listings and sells 3 or more a day ("unsure" when not).
-- Else "about even" (grey), or red when it loses at every price. A
-- bind-on-pickup or random-suffix item never gets a profit, only the cost of
-- its mats. A recipe item's profit is grey for someone who could not make it
-- (no profession, under its rank, no specialization or reputation).
-- Which recipes you know: the Professions window (TRADE_SKILL_SHOW and
-- TRADE_SKILL_LIST_UPDATE, C_TradeSkillUI) tells, and is remembered per
-- character in the saved settings (by the character's GUID, never the name);
-- NEW_RECIPE_LEARNED adds one; C_SpellBook may also say so. Before a
-- profession's window was opened once, its trainer recipes up to your rank
-- "may be known": their tips are grey, and quiet in compact mode.
-- Never crafts, never casts a spell, never sends an auction house query.
-- /gl crafts on, off or status. Plain ASCII only.

ADDON_NAME = ADDON_NAME or "GoblinLedger"
ns = ns or {}

local _G = _G
local type, tonumber, tostring, pairs, ipairs, pcall, next = type, tonumber, tostring, pairs, ipairs, pcall, next
local floor, max, min, abs = math.floor, math.max, math.min, math.abs
local smatch, sgsub, slower, sfind, sgmatch = string.match, string.gsub, string.lower, string.find, string.gmatch
local tconcat, tsort, tinsert = table.concat, table.sort, table.insert

local C = { lastError = nil, scans = 0, quotes = 0, attached = false }   -- state for /gl crafts and the tests
ns.Crafts = C

