C.R, C.V, C.RI, C.N = R, V, RI, N

local PROF_NAME = { [164] = "Blacksmithing", [186] = "Mining", [202] = "Engineering", [165] = "Leatherworking",
  [197] = "Tailoring", [171] = "Alchemy", [185] = "Cooking", [129] = "First Aid", [333] = "Enchanting" }
C.PROF_NAME = PROF_NAME
local SMELTING = 186          -- smelting is Mining's
local ROBUST_SHARE = 0.10     -- a profit must beat 10% of the mats, at every price
local THIN_AUCTIONS = 3       -- the made item behind fewer separate listings than this: its price is one seller's guess
local THIN_SOLD = 3           -- ... or fewer sold a day than this: no profit claim ("unsure")
local SOLD_CAP = 1.25         -- a sale counts at most 25% over what it sold for in the last day (as the flip ideas count it)
local MATS_SHOWN = 2          -- 4 or more mats: a tooltip names the 2 dearest ("+3 others"; all of them with Shift)
local LIVE = { "LivePrice", "LiveCheapest" }   -- the live cheapest listing: the AH code's, or without it the open AH's own
local MEMO_TTL = 2            -- seconds a quote is reused (the Professions window redraws its tooltip every frame)
local SCAN_GAP = 1            -- at most one look at the open Professions window a second
local IDEA_SHARE = 0.5        -- one seller can expect half of a day's sales (as the flip ideas count it)
local IDEA_CAP = 200          -- at most this many items made for one idea
local BASES = { "lo", "mkt", "avg" }   -- cheapest listing, AH value, 7-day average

---------------------------------------------------------------------------
-- Small helpers
---------------------------------------------------------------------------
local function isSecret(v)
  local f = ns.IsSecret
  if type(f) == "function" then return f(v) end
  return false
end

local function plain(v)
  if type(v) ~= "number" or isSecret(v) or v ~= v then return nil end
  return v
end

local function settings()
  local S = ns.settings
  if type(S) ~= "table" then
    S = {}
    ns.settings = S
  end
  return S
end

local function isOn() return settings().crafts ~= false end
C.IsOn = isOn

local function colour(key)
  local c = ns.COLORS and ns.COLORS[key]
  if type(c) == "table" then return c end
  return { 0.90, 0.88, 0.84 }
end

local function paint(text, key)
  if type(ns.Colorize) == "function" then return ns.Colorize(text, colour(key)) end
  return text
end

local function clock()
  local f = _G.GetTime
  if type(f) == "function" then
    local ok, t = pcall(f)
    if ok and plain(t) then return t end
  end
  return 0
end

local function now() return type(ns.Now) == "function" and ns.Now() or 0 end

local function money(c)
  if type(ns.MoneyIcons) == "function" then return ns.MoneyIcons(c) end
  return tostring(c) .. "c"
end

local function moneyText(c)
  if type(ns.MoneyText) == "function" then return ns.MoneyText(c) end
  return tostring(c) .. "c"
end

local function shortMoney(c)
  if type(ns.ShortMoney) == "function" then return ns.ShortMoney(c) end
  return moneyText(c)
end

-- Whole gold from 10g, whole silver from 1g, copper under it: they are estimates.
local function roundCopper(c)
  local a = abs(c)
  local r
  if a >= 100000 then
    r = floor(a / 10000 + 0.5) * 10000
  elseif a >= 10000 then
    r = floor(a / 100 + 0.5) * 100
  else
    r = floor(a + 0.5)
  end
  return c < 0 and -r or r
end
C.RoundCopper = roundCopper

local function count(n)
  n = floor((tonumber(n) or 0) + 0.5)
  if n >= 10000 then return floor(n / 1000) .. "k" end
  if n >= 1000 then return string.format("%.1fk", n / 1000) end
  return tostring(n)
end

local function say(msg)
  if type(ns.Print) == "function" then ns.Print(msg) end
end

local function hasData()
  local db = ns.db
  return type(db) == "table" and (tonumber(db.updated) or 0) > 0
end

local function dataStamp()
  local db = ns.db
  return type(db) == "table" and tonumber(db.updated) or 0
end

local function mismatch()
  local f = ns.MarketMismatch
  if type(f) ~= "function" then return false end
  local ok, r = pcall(f)
  return ok and r and true or false
end

-- Stale prices (Core's one rule, ns.AgeState: 3 hours old or more): no green or red, the lines
-- are grey (as on the enchant and consumable tips), and no craft idea.
local function stale()
  if type(ns.AgeState) ~= "function" then return false end
  local ok, st = pcall(ns.AgeState)
  return ok and st == "stale"
end

-- The name to show: the price data's or the game's, else the recipe table's.
local function nameOf(id)
  local n = type(ns.ItemName) == "function" and ns.ItemName(id) or nil
  local unknown = type(ns.IsUnknownName) == "function" and ns.IsUnknownName or function(x) return not x or x == "" end
  if type(n) == "string" and not unknown(n) and not smatch(n, "^Item %d+") then return n end
  return N[id] or n or ("Item " .. tostring(id))
end
C.NameOf = nameOf

---------------------------------------------------------------------------
-- The recipe table
---------------------------------------------------------------------------
local parsed = {}

local function getRecipe(sp)
  sp = tonumber(sp)
  if not sp then return nil end
  local c = parsed[sp]
  if c ~= nil then return c or nil end
  local raw = R[sp]
  if type(raw) ~= "string" then
    parsed[sp] = false
    return nil
  end
  local f, i = {}, 0
  for x in sgmatch(raw .. "|", "([^|]*)|") do
    i = i + 1
    f[i] = x
  end
  local fl = f[6] or ""
  local function has(ch) return sfind(fl, ch, 1, true) ~= nil end
  local r = {
    id = sp, skill = tonumber(f[1]) or 0, product = tonumber(f[2]) or 0,
    cmin = tonumber(f[3]) or 1, cmax = tonumber(f[4]) or 1, mats = {},
    rank = tonumber(f[7]), spec = tonumber(f[8]), rep = (f[9] or "") ~= "" and f[9] or nil,
    items = {}, yellow = tonumber(f[11]) or 0,
    starts = has("K"), trainer = has("T"), bop = has("B"), unsure = has("U"), suffix = has("S"),
    eraRank = has("E"), side = has("A") and "A" or (has("H") and "H" or nil), cd = tonumber(f[12]),
  }
  r.count = (r.cmin + r.cmax) / 2
  for id, n in sgmatch(f[5] or "", "(%d+):(%d+)") do r.mats[#r.mats + 1] = { id = tonumber(id), n = tonumber(n) } end
  for id in sgmatch(f[10] or "", "%d+") do r.items[#r.items + 1] = tonumber(id) end
  parsed[sp] = r
  return r
end
C.Recipe = getRecipe

-- Lists of recipe ids by product, by mat, by recipe item and by profession (built once).
local index
local function getIndex()
  if index then return index end
  local byProduct, byMat, byItem, bySkill = {}, {}, {}, {}
  local function add(t, k, v)
    local l = t[k]
    if not l then
      l = {}
      t[k] = l
    end
    l[#l + 1] = v
  end
  for sp, raw in pairs(R) do
    local sl, pid, mats, items = smatch(raw, "^(%d+)|(%d+)|%d+|%d+|([^|]*)|[^|]*|[^|]*|[^|]*|[^|]*|([^|]*)|")
    if sl then
      add(bySkill, tonumber(sl), sp)
      add(byProduct, tonumber(pid), sp)
      for id in sgmatch(mats, "(%d+):") do add(byMat, tonumber(id), sp) end
      for id in sgmatch(items, "%d+") do add(byItem, tonumber(id), sp) end
    end
  end
  for _, t in ipairs({ byProduct, byMat, byItem, bySkill }) do
    for _, l in pairs(t) do tsort(l) end
  end
  index = { byProduct = byProduct, byMat = byMat, byItem = byItem, bySkill = bySkill }
  return index
end
C.Index = getIndex

local function skillOf(sp)
  local raw = R[sp]
  return type(raw) == "string" and tonumber(smatch(raw, "^(%d+)|")) or nil
end

---------------------------------------------------------------------------
-- Faction, professions and the recipes you know
---------------------------------------------------------------------------
local function playerSide()
  local f = _G.UnitFactionGroup
  if type(f) ~= "function" then return nil end
  local ok, g = pcall(f, "player")
  if not ok or type(g) ~= "string" or isSecret(g) then return nil end
  if g == "Alliance" then return "A" end
  if g == "Horde" then return "H" end
  return nil
end

-- Not for the other faction (Earthen Ring recipes for an Alliance player, say).
local function visible(r)
  if not r then return false end
  if r.side then
    local s = playerSide()
    if s and s ~= r.side then return false end
  end
  return true
end
C.Visible = visible

-- Your rank in a profession (0 = not learned), as Enchants.lua reads it.
local function skillRank(id)
  local E = ns.Enchants
  if type(E) == "table" and type(E.SkillRank) == "function" then
    local ok, r = pcall(E.SkillRank, id)
    if ok and type(r) == "number" then return r end
  end
  return 0
end
C.SkillRank = skillRank

-- The skill list can be read (so a rank of 0 means "not learned").
local function skillsReadable()
  local CS = _G.C_SkillInfo
  if type(CS) == "table" and type(CS.GetNumSkillLines) == "function" then
    local ok, n = pcall(CS.GetNumSkillLines)
    if ok and plain(n) and n > 0 then return true end
  end
  local f = _G.GetNumSkillLines
  if type(f) == "function" then
    local ok, n = pcall(f)
    if ok and plain(n) and n > 0 then return true end
  end
  return false
end

-- What is remembered for this character: known[recipe] = true, scanned[profession] = when
-- its window showed the learned recipes. Kept in the saved settings by the character's GUID.
local session = { known = {}, scanned = {} }

local function charKey()
  local f = _G.UnitGUID
  if type(f) ~= "function" then return nil end
  local ok, g = pcall(f, "player")
  if ok and type(g) == "string" and not isSecret(g) and g ~= "" then return g end
  return nil
end

local function store()
  local key = charKey()
  if not key or not ns.settingsLoaded then return session end
  local S = settings()
  local all = S.craftChars
  if type(all) ~= "table" then
    all = {}
    S.craftChars = all
  end
  local st = all[key]
  if type(st) ~= "table" then
    st = { v = 1 }
    all[key] = st
  end
  if type(st.known) ~= "table" then st.known = {} end
  if type(st.scanned) ~= "table" then st.scanned = {} end
  -- What this session saw before the saved settings were loaded.
  if next(session.known) or next(session.scanned) then
    for k, v in pairs(session.known) do st.known[k] = v end
    for k, v in pairs(session.scanned) do st.scanned[k] = v end
    session.known, session.scanned = {}, {}
  end
  return st
end
C.Store = store

-- The game's spell book says the recipe is known (only a yes is trusted).
local spellMemo = {}
local function spellKnown(sp)
  local m = spellMemo[sp]
  if m ~= nil then return m end
  local SB, yes = _G.C_SpellBook, false
  if type(SB) == "table" then
    if type(SB.IsSpellInSpellBook) == "function" then
      local ok, r = pcall(SB.IsSpellInSpellBook, sp, 0, false)
      if ok and not isSecret(r) and r == true then yes = true end
    end
    if not yes and type(SB.IsSpellKnown) == "function" then
      local ok, r = pcall(SB.IsSpellKnown, sp, 0)
      if ok and not isSecret(r) and r == true then yes = true end
    end
  end
  spellMemo[sp] = yes
  return yes
end

-- "known", "maybe" (a trainer recipe up to your rank, before the profession's window
-- was opened once) or nil.
local function knownState(r)
  if not r then return nil end
  local st = store()
  if st.known[r.id] or spellKnown(r.id) then return "known" end
  local rank = skillRank(r.skill)
  if rank <= 0 then return nil end
  if r.starts then return "known" end
  if st.scanned[r.skill] then return nil end
  if r.trainer and not r.spec and not r.rep and rank >= (r.rank or r.yellow or 1) then return "maybe" end
  return nil
end
C.KnownState = function(sp) return knownState(getRecipe(sp)) end

-- Your standing with a faction is at least the recipe's ("529:5": Argent Dawn, Honored; the
-- standing counts from 0 = Hated, the game's reaction from 1). Unreadable: no.
local function repMet(rep)
  local fid, need = smatch(rep or "", "^(%d+):(%d+)$")
  fid, need = tonumber(fid), tonumber(need)
  if not fid then return false end
  local CR, re = _G.C_Reputation, nil
  if type(CR) == "table" and type(CR.GetFactionDataByID) == "function" then
    local ok, d = pcall(CR.GetFactionDataByID, fid)
    if ok and type(d) == "table" then re = plain(d.reaction) end
  end
  if not re and type(_G.GetFactionInfoByID) == "function" then
    local ok, _, _, standing = pcall(_G.GetFactionInfoByID, fid)
    re = ok and plain(standing) or nil
  end
  return re ~= nil and re >= need + 1
end

-- You could make it: you know it, or you have its profession at its rank, its specialization
-- (Armorsmith ...) and its reputation. Else a recipe item's profit is grey (no claim for you).
local function canMake(r)
  if not r then return false end
  if knownState(r) == "known" then return true end
  local rank = skillRank(r.skill)
  if rank <= 0 or rank < (r.rank or 0) then return false end
  if r.spec and not spellKnown(r.spec) then return false end
  if r.rep and not repMet(r.rep) then return false end
  return true
end
C.CanMake = function(sp) return canMake(getRecipe(sp)) end

---------------------------------------------------------------------------
-- Prices and the sums
---------------------------------------------------------------------------
-- The live cheapest listing the open auction house showed (per unit), and whether it is
-- yours; nil when there is none. The AH code's ns.LivePrice answers for itself: its nil (no
-- listing, or another market whose prices do not mix with the data's) is not asked again of
-- the open AH's own listings, which are only for an AH code without it.
local function liveOf(id)
  for _, name in ipairs(LIVE) do
    local f = ns[name]
    if type(f) == "function" then
      local ok, p, own = pcall(f, id)
      p = ok and plain(p) or nil
      if p and p > 0 then return floor(p), not isSecret(own) and own == true end
      return nil
    end
  end
  return nil
end

-- One item's prices: lo (the cheapest listing: live, else the data's), mkt (AH value),
-- avg (7-day average), vendor (what an Alliance vendor sells it for), item; own (the live
-- cheapest is yours: not one to buy, and matched rather than undercut), dataLo (the data's).
local function pricesOf(id)
  local it = type(ns.GetItem) == "function" and ns.GetItem(id) or nil
  local p = { vendor = V[id], item = it }
  if it then
    if (tonumber(it.cheapest) or 0) > 0 then p.lo = it.cheapest end
    if (tonumber(it.market) or 0) > 0 then p.mkt = it.market end
    if (tonumber(it.avg7) or 0) > 0 then p.avg = it.avg7 end
  end
  local live, own = liveOf(id)
  if live then p.dataLo, p.lo, p.live, p.own = p.lo, live, true, own end
  return p
end

-- The most a made item counts at: 25% over what it sold for in the last day (Sidebar.lua's
-- DayStats), or nil when its sales are not measured.
local function soldCap(id)
  local f = ns.DayStats
  if type(f) ~= "function" then return nil end
  local ok, st = pcall(f, id)
  local at = ok and type(st) == "table" and plain(st.soldAt) or nil
  if at and at > 0 then return floor(SOLD_CAP * at) end
  return nil
end

-- What a mat costs each on a basis (nil: no price), and whether a vendor's price it is.
local function buyAt(p, basis)
  local x
  if basis == "lo" then
    if p.own then x = p.dataLo or p.mkt else x = p.lo or p.mkt end
  elseif basis == "mkt" then
    x = p.mkt or p.lo
  else
    x = p.avg
  end
  if p.vendor and (not x or p.vendor < x) then return p.vendor, true end
  return x, false
end

-- The price the item's own tooltip says to sell it at, from the one rule for it (Recommend.lua's
-- ns.SellAt, which the tooltip's ns.SellPrices uses too) with the live listing the tooltip uses
-- (p: pricesOf; the AH code's ns.LivePrice is the listing Core.lua's Sell now (live) follows):
-- Sell now, 1c under the cheapest listing (yours: matched), or the usual price when Sell now is
-- under 70% of it (the yellow "Sell now (38% under usual)" and its "Sell at"); nothing listed:
-- the usual price. When the tooltip gives none because the price may be one player's guess (a
-- few units far above what a vendor pays: "Few listed"), its Sell now before that doubt and
-- true: a profit is never claimed at it. nil when there is neither.
local function tooltipSellAt(id, p)
  local f = ns.SellAt
  if type(f) ~= "function" then return nil end
  local ok, P = pcall(f, id, p.live and p.lo or nil, p.own == true)
  if not ok or type(P) ~= "table" then return nil end
  local at = plain(P.at)
  if at and at > 0 then return at, false end
  local raw = P.atWhy == "unreliable" and plain(P.raw) or nil
  if raw and raw > 0 then return raw, true end
  return nil
end

-- What the made item sells for each on a basis: at the cheapest prices, the tooltip's own
-- price to sell at (so the profit follows the Sell now / Sell at lines above it); at AH value
-- that, but never 25% over what it sold for in the last day; the 7-day average.
local function sellAt(p, basis)
  if basis == "lo" then return p.at end
  if basis == "mkt" then
    local s = p.mkt
    if s and p.cap and s > p.cap then s = p.cap end
    return s
  end
  return p.avg
end

local function soldPerDay(item)
  if not item or type(ns.SoldPerDay) ~= "function" then return nil end
  local ok, n = pcall(ns.SoldPerDay, item)
  return ok and plain(n) or nil
end

local function hasVersions(id)
  local f = ns.HasVariants
  if type(f) ~= "function" then return false end
  local ok, r = pcall(f, id)
  return ok and r == true
end

local quoteMemo, memoKey = {}, nil
local function memoFresh()
  local k = tostring(dataStamp())
  if memoKey ~= k then
    quoteMemo, memoKey = {}, k
  end
end

local quote
-- The cheapest recipe you know that makes a mat, per unit on each basis: unit, recipe.
local function subFor(mid, parent)
  local list = getIndex().byProduct[mid]
  if not list then return nil end
  local best, bestR
  for _, sp in ipairs(list) do
    local r2 = getRecipe(sp)
    if r2 and r2 ~= parent and visible(r2) and knownState(r2) == "known" then
      local loops = false
      for _, m in ipairs(r2.mats) do
        if m.id == parent.product then loops = true end
      end
      local q2 = not loops and quote(r2, 1) or nil
      if q2 and q2.missing == 0 and q2.cost.lo then
        local u = {}
        for _, b in ipairs(BASES) do u[b] = q2.cost[b] and q2.cost[b] / r2.count or nil end
        if not best or u.lo < best.lo then best, bestR = u, r2 end
      end
    end
  end
  return best, bestR
end

-- Everything about making a recipe once at today's prices:
--   mats[i] = { id, n, cost = { lo, mkt, avg }, vendor, sub (the recipe you make it with), live }
--   cost / sellUnit / net / profit = { lo, mkt, avg } (nil: no price on that basis)
--   missing (mats with no price at all), sells (what the made items sell for, before the cut),
--   sold (the item's sales a day), verdict "profit" / "even" / "loss" (nil: no claim), live.
-- depth 1 is a mat you make yourself: no deeper than that.
quote = function(r, depth)
  depth = depth or 0
  memoFresh()
  local key = depth > 0 and (r.id .. "s") or r.id
  local m = quoteMemo[key]
  local t = clock()
  if m and t - m.at < MEMO_TTL and t >= m.at then return m.q end
  C.quotes = C.quotes + 1
  local q = { r = r, mats = {}, cost = { lo = 0, mkt = 0, avg = 0 }, sellUnit = {}, net = {}, profit = {}, missing = 0, partial = 0 }
  for _, mat in ipairs(r.mats) do
    local p = pricesOf(mat.id)
    local e = { id = mat.id, n = mat.n, cost = {}, live = p.live }
    local unit, vend = {}, {}
    for _, b in ipairs(BASES) do unit[b], vend[b] = buyAt(p, b) end
    if depth == 0 then
      local su, sr = subFor(mat.id, r)
      if su and (not unit.lo or su.lo < unit.lo) then
        e.sub = sr
        for _, b in ipairs(BASES) do
          if su[b] and (not unit[b] or su[b] < unit[b]) then unit[b], vend[b] = su[b], false end
        end
      end
    end
    e.vendor = vend.lo == true and not e.sub
    for _, b in ipairs(BASES) do
      if unit[b] then
        e.cost[b] = floor(unit[b] * mat.n + 0.5)
        if q.cost[b] then q.cost[b] = q.cost[b] + e.cost[b] end
      else
        q.cost[b] = nil
      end
    end
    if unit.lo then q.partial = q.partial + e.cost.lo else q.missing = q.missing + 1 end
    if p.live then q.live = true end
    q.mats[#q.mats + 1] = e
  end
  local pp = pricesOf(r.product)
  pp.cap = soldCap(r.product)
  pp.at, q.doubt = tooltipSellAt(r.product, pp)
  if pp.live then q.live = true end
  for _, b in ipairs(BASES) do
    local s = sellAt(pp, b)
    if s and s > 0 then
      q.sellUnit[b] = s
      q.net[b] = floor(s * r.count * 95 / 100)   -- the auction house keeps 5%
      if q.cost[b] then q.profit[b] = q.net[b] - q.cost[b] end
    end
  end
  if q.sellUnit.lo then q.sells = floor(q.sellUnit.lo * r.count + 0.5) end
  q.sold = soldPerDay(pp.item)
  q.item = pp.item
  q.suffix = r.suffix or hasVersions(r.product)
  -- Thin: 1 or 2 separate listings of the made item (one seller's price), under 3 sold a day,
  -- or a price its tooltip doubts (a few units far above what a vendor pays).
  local auctions = pp.item and plain(tonumber(pp.item.auctions)) or nil
  if auctions and auctions >= 1 and auctions < THIN_AUCTIONS then
    q.thin, q.auctions = "listings", auctions
  elseif (q.sold or 0) < THIN_SOLD then
    q.thin = "sales"
  elseif q.doubt then
    q.thin = "doubt"
  end
  local P = q.profit
  if r.bop or r.unsure or q.suffix or q.missing > 0 or not P.lo then
    q.verdict = nil
  else
    -- a profit: more than 10% of the mats at every price (the smallest one is the one shown);
    -- a loss: under 0 at every price there is (shown at today's cheapest prices)
    local good, bad, low = true, true, nil
    for _, b in ipairs(BASES) do
      local x = P[b]
      if x then
        if not (x > ROBUST_SHARE * q.cost[b]) then good = false end
        if x >= 0 then bad = false end
        low = low and min(low, x) or x
      else
        good = false
      end
    end
    if good and not q.thin then
      q.verdict, q.shown = "profit", low
    elseif good then
      q.verdict = "thin"
    elseif bad then
      q.verdict, q.shown = "loss", P.lo
    else
      q.verdict = "even"
    end
  end
  quoteMemo[key] = { at = t, q = q }
  return q
end
C.Quote = function(sp)
  local r = getRecipe(sp)
  return r and quote(r) or nil
end

---------------------------------------------------------------------------
-- The words
---------------------------------------------------------------------------
local function countPrefix(r)
  if r.cmin == r.cmax then return r.cmin ~= 1 and (r.cmin .. " ") or "" end
  return r.cmin .. "-" .. r.cmax .. " "
end

local function shiftDown()
  local f = _G.IsShiftKeyDown
  if type(f) ~= "function" then return false end
  local ok, r = pcall(f)
  return ok and not isSecret(r) and r and true or false   -- older clients answer 1
end

-- With 4 or more mats, the 2 dearest to name: { [i] = true }, else nil (all). Unpriced ones first
-- (they say "(no price)"), or with pricedFirst last.
local function dearest(list, pricedFirst)
  if #list <= MATS_SHOWN + 1 then return nil end
  local order = {}
  for i = 1, #list do order[i] = i end
  tsort(order, function(a, b)
    local ca, cb = list[a].cost.lo, list[b].cost.lo
    if (ca == nil) ~= (cb == nil) then return (ca == nil) ~= (pricedFirst == true) end
    if ca and ca ~= cb then return ca > cb end
    return a < b
  end)
  local keep = {}
  for i = 1, MATS_SHOWN do keep[order[i]] = true end
  return keep
end

-- " (from 12 Heavy Stone)": a mat you make yourself, priced as its own mats.
local function fromText(e)
  local from = {}
  for _, m in ipairs(e.sub.mats) do
    from[#from + 1] = floor(e.n / e.sub.count * m.n + 0.5) .. " " .. nameOf(m.id)
  end
  return #from > 0 and (" (from " .. tconcat(from, " + ") .. ")") or ""
end

-- "4 Heavy Grinding Stone 59s (from 12 Heavy Stone), 4 Coal 20s (vendor), 2 Black Pearl (no price)".
-- With the costs and 4 or more mats, only the 2 dearest (unpriced ones first) unless `all` or
-- Shift: "12 Arcanite Bar 552g, 10 Blue Sapphire 53g, +3 others".
local function matsText(q, withCost, all)
  local list, keep = q.mats, nil
  if withCost and not all and #list > MATS_SHOWN + 1 and not shiftDown() then keep = dearest(list) end
  local parts = {}
  for i, e in ipairs(list) do
    if not keep or keep[i] then
      local s = e.n .. " " .. nameOf(e.id)
      if withCost then
        if e.cost.lo then s = s .. " " .. moneyText(roundCopper(e.cost.lo)) else s = s .. " (no price)" end
        if e.sub then
          s = s .. fromText(e)
        elseif e.vendor then
          s = s .. " (vendor)"
        end
      end
      parts[#parts + 1] = s
    end
  end
  if keep then parts[#parts + 1] = "+" .. (#list - MATS_SHOWN) .. " others" end
  return tconcat(parts, ", ")
end
C.MatsText = matsText

-- "1g 23s", or "1g 23s + 2 more" when some mats have no price, "price unknown" when none has
-- one (never "0c").
local function totalText(q, plainMoney)
  if not q.cost.lo and (q.partial or 0) <= 0 then return "price unknown" end
  local fn = plainMoney and moneyText or money
  local t = fn(roundCopper(q.cost.lo or q.partial or 0))
  if q.missing > 0 then t = t .. " + " .. q.missing .. " more" end
  return t
end

-- "unsure, 2 listings" / "unsure, few sales": it would pay, but the made item's price is thin.
local function unsureText(q)
  if q.thin == "listings" then
    return "unsure, " .. q.auctions .. (q.auctions == 1 and " listing" or " listings")
  end
  if q.thin == "doubt" then return "unsure, few listed" end   -- the tooltip's "Few listed" line
  return "unsure, few sales"
end

-- The profit words and their colour key, or nil (no claim for this item).
local function profitText(q)
  local p = q.shown
  if q.verdict == "profit" then return "Profit: +" .. money(roundCopper(p)), "pos" end
  if q.verdict == "loss" then return "Profit: " .. money(roundCopper(p)), "neg" end
  if q.verdict == "even" then return "Profit: about even", "muted" end
  if q.verdict == "thin" then return "Profit: " .. unsureText(q), "muted" end
  return nil
end

---------------------------------------------------------------------------
-- Tooltip lines (called by Core.lua's handlers)
---------------------------------------------------------------------------
local TIPS = { GameTooltip = true, ItemRefTooltip = true }   -- not the comparison tooltips

-- A tooltip our own rows own: the row says what it is about.
local function quietOwner(tt)
  if type(tt.GetOwner) ~= "function" then return false end
  local ok, owner = pcall(tt.GetOwner, tt)
  return ok and type(owner) == "table" and (owner.glNoEnchants == true or owner.glNoCraft == true)
end

-- The "Mats: 1g 23s   Profit: +2g 8s" line (grey when quiet).
local function totalLine(tt, q, quiet)
  local tx, mu = colour("text"), colour("muted")
  local left = "Mats: " .. totalText(q)
  local pt, pc = profitText(q)
  if pt then
    local rc = colour(quiet and "muted" or pc)
    local lc = quiet and mu or tx
    tt:AddDoubleLine(left, pt, lc[1], lc[2], lc[3], rc[1], rc[2], rc[3])
  else
    local lc = quiet and mu or tx
    tt:AddLine(left, lc[1], lc[2], lc[3])
  end
end

-- A recipe item, for everyone: what it makes and sells for, the mats, and the profit.
local function recipeItemLines(tt, id, compact)
  local list = getIndex().byItem[id]
  if not list then return false end
  local r
  for _, sp in ipairs(list) do
    local x = getRecipe(sp)
    if visible(x) then
      r = x
      break
    end
  end
  if not r then return false end
  local q = quote(r)
  local old = stale()
  local quiet = old or not canMake(r)   -- a profit only for someone who could make it
  local tx, mu, wh = colour("text"), colour("muted"), { 1, 1, 1 }
  if not compact then
    if r.bop then
      tt:AddLine("Makes a bind-on-pickup item", tx[1], tx[2], tx[3])
    else
      local right, rc = nil, wh
      if q.suffix then
        right, rc = "price varies by version", mu
      elseif q.sells then
        right = money(roundCopper(q.sells))
      else
        right, rc = "no AH price", mu
      end
      local lc = old and mu or tx   -- stale prices: the line grey
      if old then rc = mu end
      tt:AddDoubleLine("Makes: " .. countPrefix(r) .. nameOf(r.product), right, lc[1], lc[2], lc[3], rc[1], rc[2], rc[3])
    end
    tt:AddLine(matsText(q, true), mu[1], mu[2], mu[3], true)
  end
  totalLine(tt, q, quiet)
  return true
end

-- The recipe for a crafted item: the one the Professions window shows, else the one you
-- know (known before "maybe"), the cheapest to make. Returns recipe, state.
local function productRecipe(id, info)
  if type(info) == "table" and info.getterName == "GetRecipeResultItem" and type(info.getterArgs) == "table" then
    local r = getRecipe(info.getterArgs[1])
    if r and r.product == id and visible(r) then return r, knownState(r) or "shown" end
  end
  local list = getIndex().byProduct[id]
  if not list then return nil end
  local best, bestState, bestCost
  for _, sp in ipairs(list) do
    local r = getRecipe(sp)
    local s = visible(r) and knownState(r) or nil
    if s then
      local cost = quote(r).cost.lo or math.huge
      local better = not best or (s == "known" and bestState ~= "known")
        or (s == bestState and cost < bestCost)
      if better then best, bestState, bestCost = r, s, cost end
    end
  end
  return best, bestState
end

local function productLines(tt, id, info, compact)
  local r, state = productRecipe(id, info)
  if not r then return false end
  local q = quote(r)
  local quiet = state ~= "known" or stale()
  if not compact then
    local mu = colour("muted")
    -- "Smelt: 1 Iron Ore 2s 44c": what making it yourself takes
    tt:AddLine((r.skill == SMELTING and "Smelt: " or "Make: ") .. matsText(q, true), mu[1], mu[2], mu[3], true)
  end
  totalLine(tt, q, quiet)
  return true
end

-- A mat: the best recipe you know that uses it. Known ones before "maybe" ones, then a
-- profit before about even before a loss, then the most for each of this mat (a craft's
-- profit over how many of it the craft takes: 8 Dark Iron Ore make a bar). Not a thin one.
local RANK = { profit = 3, even = 2, loss = 1 }
local function keyAbove(a, b)
  for i = 1, #a do
    if a[i] ~= b[i] then return a[i] > b[i] end
  end
  return false
end
local function reagentPick(id)
  local list = getIndex().byMat[id]
  if not list then return nil end
  local best, bestKey
  for _, sp in ipairs(list) do
    local r = getRecipe(sp)
    if r and r.product ~= id and not r.bop and not r.unsure and not r.suffix and visible(r) then
      local s = knownState(r)
      if s then
        local q = quote(r)
        if RANK[q.verdict] then
          local n = 1
          for _, m in ipairs(r.mats) do
            if m.id == id then n = m.n end
          end
          local each = (q.shown or q.profit.lo) / n
          local k = { s == "known" and 1 or 0, RANK[q.verdict], each, -r.id }
          if not bestKey or keyAbove(k, bestKey) then best, bestKey = { r = r, q = q, state = s, each = each }, k end
        end
      end
    end
  end
  return best
end
C.ReagentPick = reagentPick

local function reagentLabel(r)
  return (r.skill == SMELTING and "Smelt to " or "Make ") .. nameOf(r.product)
end

local function reagentLines(tt, id, compact)
  local b = reagentPick(id)
  if not b then return false end
  local quiet = b.state ~= "known" or stale()
  if compact and (quiet or b.q.verdict ~= "profit") then return false end
  local each = floor(b.each)
  if each < 0 then each = -floor(-b.each) end
  local right, key
  if b.q.verdict == "profit" then
    right, key = "+" .. money(roundCopper(each)) .. " each", "pos"
  elseif b.q.verdict == "loss" then
    right, key = money(roundCopper(each)) .. " each", "neg"
  else
    right, key = "about even", "muted"
  end
  local lc = colour(quiet and "muted" or "text")
  local rc = colour(quiet and "muted" or key)
  tt:AddDoubleLine(reagentLabel(b.r), right, lc[1], lc[2], lc[3], rc[1], rc[2], rc[3])
  return true
end

local function addLines(tt, itemID, info)
  local S = settings()
  if S.crafts == false or S.tooltip == false or ns.tipQuiet then return false end
  if type(tt) ~= "table" or type(tt.GetName) ~= "function" then return false end
  local okN, name = pcall(tt.GetName, tt)
  if not okN or isSecret(name) or not TIPS[name] then return false end
  if quietOwner(tt) then return false end
  if not hasData() or mismatch() then return false end
  local id = plain(itemID)
  if not id then return false end
  if type(ns.BaseItemID) == "function" then id = ns.BaseItemID(id) or id end
  local compact = S.compact == true
  local idx = getIndex()
  local added = false
  if idx.byItem[id] then
    added = recipeItemLines(tt, id, compact)
  end
  if idx.byProduct[id] and productLines(tt, id, info, compact) then added = true end
  if idx.byMat[id] and reagentLines(tt, id, compact) then added = true end
  return added
end

-- true when lines were added. Never raises: an error is kept in ns.Crafts.lastError.
function ns.CraftLines(tt, itemID, info)
  local ok, r = pcall(addLines, tt, itemID, info)
  if not ok then
    C.lastError = r
    return false
  end
  return r == true
end

---------------------------------------------------------------------------
-- The Professions window: one line for the recipe you picked
---------------------------------------------------------------------------
-- Forever's ProfessionsFrame (Blizzard_Professions, Camelot): the CraftingPage's
-- SchematicForm (360 x 484) has the reagents under the description and, at the bottom
-- right, the Track Recipe check box (BOTTOMRIGHT, -(label width + 20), 11; its label on
-- its right). Under the form the page's bar holds Create All, the count box and Create.
-- The line sits in the form's empty bottom left corner, left of the check box (above the
-- "use best quality" box when that shows), wrapping to a second line when it must.
local LINE_X, LINE_Y, LINE_GAP = 20, 14, 8
local PW = { fs = nil, form = nil }
C.PW = PW

-- "Mats 1g 23s - sells 3g 31s - +2g 8s after AH cut" (or "loses 45s after AH cut", "about even after AH cut")
local function professionsText(r)
  local q = quote(r)
  local old = stale()
  local parts = { "Mats " .. totalText(q, true) }
  if r.bop then
    parts[2] = "bind on pickup"
  elseif q.suffix then
    parts[2] = "price varies by version"
  elseif q.sells then
    parts[2] = "sells " .. moneyText(roundCopper(q.sells))
    local p = q.shown
    local quiet = old or not canMake(r)
    if q.verdict == "profit" then
      parts[3] = paint("+" .. moneyText(roundCopper(p)) .. " after AH cut", quiet and "muted" or "pos")
    elseif q.verdict == "loss" then
      parts[3] = paint("loses " .. moneyText(roundCopper(-p)) .. " after AH cut", quiet and "muted" or "neg")
    elseif q.verdict == "even" then
      parts[3] = paint("about even after AH cut", "muted")
    elseif q.verdict == "thin" then
      parts[3] = paint(unsureText(q), "muted")
    end
  else
    parts[2] = "no AH price"
  end
  if old then   -- stale prices: the mats and the sale grey too (the profit already is)
    parts[1] = paint(parts[1], "muted")
    if parts[2] then parts[2] = paint(parts[2], "muted") end
  end
  return tconcat(parts, " - ")
end
C.ProfessionsText = function(sp)
  local r = getRecipe(sp)
  return r and professionsText(r) or nil
end

local function shownFrame(f)
  if type(f) ~= "table" or type(f.IsShown) ~= "function" then return false end
  local ok, s = pcall(f.IsShown, f)
  return ok and s == true
end

local function placeLine(fs, form)
  pcall(fs.ClearAllPoints, fs)
  local best = form.AllocateBestQualityCheckbox
  if shownFrame(best) then
    pcall(fs.SetPoint, fs, "BOTTOMLEFT", best, "TOPLEFT", 0, 4)
  else
    pcall(fs.SetPoint, fs, "BOTTOMLEFT", form, "BOTTOMLEFT", LINE_X, LINE_Y)
  end
  local track = form.TrackRecipeCheckbox
  if type(track) == "table" and type(track.GetLeft) == "function" then
    pcall(fs.SetPoint, fs, "RIGHT", track, "LEFT", -LINE_GAP, 0)
  else
    pcall(fs.SetPoint, fs, "RIGHT", form, "RIGHT", -LINE_X, 0)
  end
end

local function currentRecipeID(form)
  local info
  if type(form.GetRecipeInfo) == "function" then
    local ok, x = pcall(form.GetRecipeInfo, form)
    if ok then info = x end
  end
  if type(info) ~= "table" then info = form.currentRecipeInfo end
  if type(info) ~= "table" then return nil end
  return plain(info.recipeID)
end

local function refreshProfessions()
  local fs, form = PW.fs, PW.form
  if not fs or not form then return end
  local sp = currentRecipeID(form)
  local r = sp and getRecipe(sp)
  if not r or not isOn() or not hasData() or mismatch() or not visible(r) then
    pcall(fs.Hide, fs)
    PW.recipe = nil
    return
  end
  placeLine(fs, form)
  pcall(fs.SetText, fs, professionsText(r))
  pcall(fs.Show, fs)
  PW.recipe = sp
end
C.RefreshProfessions = function()
  local ok, err = pcall(refreshProfessions)
  if not ok then C.lastError = err end
end

local function attachProfessions()
  local PF = _G.ProfessionsFrame
  local page = type(PF) == "table" and PF.CraftingPage or nil
  local form = type(page) == "table" and page.SchematicForm or nil
  if type(form) ~= "table" or type(form.CreateFontString) ~= "function" then return false end
  if PW.form == form then return true end
  local ok, fs = pcall(form.CreateFontString, form, nil, "OVERLAY", "GameFontHighlightSmall")
  if not ok or type(fs) ~= "table" then return false end
  PW.form, PW.fs = form, fs
  pcall(fs.SetJustifyH, fs, "LEFT")
  pcall(fs.SetJustifyV, fs, "BOTTOM")
  if type(fs.SetWordWrap) == "function" then pcall(fs.SetWordWrap, fs, true) end
  if type(fs.SetMaxLines) == "function" then pcall(fs.SetMaxLines, fs, 2) end
  pcall(fs.Hide, fs)
  -- A new recipe picked: the form's Init runs (ProfessionsCraftingPageMixin:SelectRecipe).
  if type(form.Init) == "function" and type(_G.hooksecurefunc) == "function" then
    pcall(_G.hooksecurefunc, form, "Init", C.RefreshProfessions)
  end
  if type(form.HookScript) == "function" then pcall(form.HookScript, form, "OnShow", C.RefreshProfessions) end
  local ER = _G.EventRegistry
  if type(ER) == "table" and type(ER.RegisterCallback) == "function" then
    pcall(ER.RegisterCallback, ER, "ProfessionsRecipeListMixin.Event.OnRecipeSelected", C.RefreshProfessions, C)
  end
  C.attached = true
  C.RefreshProfessions()
  return true
end
C.AttachProfessions = function()
  local ok, r = pcall(attachProfessions)
  if not ok then C.lastError = r end
  return ok and r
end

---------------------------------------------------------------------------
-- Reading the Professions window: which recipes this character knows
---------------------------------------------------------------------------
local NOT_MINE = { "IsTradeSkillLinked", "IsTradeSkillGuild", "IsTradeSkillGuildMember", "IsNPCCrafting", "IsRuneforging" }
local tableAsked = {}   -- professions whose recipes in our table were asked about this session

local function tsCall(T, name, ...)
  local f = T[name]
  if type(f) ~= "function" then return nil end
  local ok, a = pcall(f, ...)
  if ok and not isSecret(a) then return a end
  return nil
end

local function invalidate()
  spellMemo = {}
  quoteMemo, memoKey = {}, nil
  local SB = ns.SidebarPanel
  if type(SB) == "table" then SB.flipsDirty = true end
end
C.Invalidate = invalidate

local function scan()
  C.lastScanAt = clock()
  local T = _G.C_TradeSkillUI
  if type(T) ~= "table" then return 0 end
  if tsCall(T, "IsDataSourceChanging") == true then return 0 end
  if tsCall(T, "IsTradeSkillReady") == false then return 0 end   -- the recipes have not loaded yet
  for _, n in ipairs(NOT_MINE) do
    if tsCall(T, n) == true then return 0 end   -- someone else's recipes
  end
  local info = tsCall(T, "GetChildProfessionInfo")
  if type(info) ~= "table" or not plain(info.professionID) or info.professionID == 0 then info = tsCall(T, "GetBaseProfessionInfo") end
  local skill
  if type(info) == "table" then
    skill = plain(info.parentProfessionID)
    if not skill or skill == 0 then skill = plain(info.professionID) end
  end
  local st = store()
  local seen, got, answered, skills = {}, 0, 0, {}
  local function look(id)
    id = plain(id)
    if not id or seen[id] then return end
    seen[id] = true
    local ri = tsCall(T, "GetRecipeInfo", id)
    if type(ri) ~= "table" then return end
    answered = answered + 1
    if not isSecret(ri.learned) and ri.learned == true and R[id] then
      st.known[id] = true
      got = got + 1
      skills[skillOf(id) or 0] = true
    end
  end
  for _, fname in ipairs({ "GetAllRecipeIDs", "GetFilteredRecipeIDs" }) do
    local ids = tsCall(T, fname)
    if type(ids) == "table" then
      for i = 1, min(#ids, 3000) do look(ids[i]) end
    end
  end
  -- The open profession's recipes in our table too, once a session (a search or a filter may
  -- hide some from the window's list; one learned later comes with NEW_RECIPE_LEARNED).
  if skill and PROF_NAME[skill] and not tableAsked[skill] then
    local before = answered
    for _, sp in ipairs(getIndex().bySkill[skill] or {}) do
      if not st.known[sp] then look(sp) end
    end
    -- asked again next time unless the window answered and said something is learned
    if answered > before and got > 0 then tableAsked[skill] = true end
  end
  -- The window answered (and something is learned: a list that has not loaded says nothing is):
  -- from now on only what it says is learned counts for that profession.
  if answered > 0 and got > 0 then
    if skill and PROF_NAME[skill] then st.scanned[skill] = now() end
    for sk in pairs(skills) do
      if PROF_NAME[sk] then st.scanned[sk] = now() end
    end
  end
  C.scans = C.scans + 1
  invalidate()
  return got
end
C.Scan = function()
  local ok, r = pcall(scan)
  if not ok then
    C.lastError = r
    return 0
  end
  return r
end

local scanQueued = false
local function scanSoon()
  local last = C.lastScanAt
  local t = clock()
  if not last or t - last >= SCAN_GAP or t < last then
    C.Scan()
    return
  end
  if scanQueued then return end
  local CT = _G.C_Timer
  if type(CT) ~= "table" or type(CT.After) ~= "function" then return end
  scanQueued = true
  pcall(CT.After, SCAN_GAP, function()
    scanQueued = false
    C.Scan()
    C.RefreshProfessions()
  end)
end

local function learned(id)
  id = plain(id)
  if not id or not R[id] then return end
  store().known[id] = true
  invalidate()
end
C.Learned = learned

-- A profession unlearned (its rank is 0 in a skill list that can be read): forget its recipes.
local function dropUnlearned()
  if not skillsReadable() then return end
  local st = store()
  local gone = {}
  for sk in pairs(PROF_NAME) do
    if skillRank(sk) <= 0 then gone[sk] = true end
  end
  for sp in pairs(st.known) do
    local sk = skillOf(sp)
    if not sk or gone[sk] then st.known[sp] = nil end
  end
  for sk in pairs(st.scanned) do
    if gone[sk] then st.scanned[sk] = nil end
  end
end

local dropQueued = false
local function dropSoon()
  if dropQueued then return end
  local CT = _G.C_Timer
  if type(CT) ~= "table" or type(CT.After) ~= "function" then
    dropUnlearned()
    return
  end
  dropQueued = true
  pcall(CT.After, 0.5, function()
    dropQueued = false
    local ok, err = pcall(dropUnlearned)
    if not ok then C.lastError = err end
    invalidate()
  end)
end

---------------------------------------------------------------------------
-- Flip ideas: one from your own recipes (Sidebar.lua's ns.FlipIdeas)
---------------------------------------------------------------------------
-- The recipes you know that pay at every price and whose item sells, as flip ideas sized
-- to your gold, best first: { id = item made, kind = "craft", recipe, crafts, units, cost,
-- profit, fit, dayProfit, rate, searchID (the mat to buy), and the row's words }.
local function listedOf(id)
  local it = type(ns.GetItem) == "function" and ns.GetItem(id) or nil
  return it and tonumber(it.listed) or 0
end

local function craftIdeas(gold)
  if not isOn() or not hasData() or mismatch() or stale() then return {} end
  if gold == nil and type(ns.PlayerGold) == "function" then gold = ns.PlayerGold() end
  local dayValue = ns.DayValue
  if type(dayValue) ~= "function" then return {} end
  local out = {}
  local idx = getIndex()
  local S = settings()
  local hidden = type(S.flipHidden) == "table" and S.flipHidden or {}
  local t = now()
  for sk in pairs(PROF_NAME) do
    if skillRank(sk) > 0 then
      for _, sp in ipairs(idx.bySkill[sk] or {}) do
        local r = getRecipe(sp)
        local h = r and hidden[r.product]
        if r and not r.bop and not r.unsure and not r.suffix and visible(r) and not (type(h) == "number" and h > t)
           and knownState(r) == "known" then
          local q = quote(r)
          local per = q.sold
          -- a cooldown (Mooncloth 95h, transmutes 23h): at most that many in a day, none over a day
          local perDay = r.cd and r.cd > 0 and floor(24 / r.cd) or nil
          if q.verdict == "profit" and per and per > 0 and q.cost.lo > 0 and (not perDay or perDay >= 1) then
            local rate = IDEA_SHARE * per
            local want = max(1, min(IDEA_CAP, floor(rate + 0.5)))
            local crafts = max(1, math.ceil(want / r.count))
            if perDay then crafts = min(crafts, perDay) end
            -- no more than the listings hold (vendor mats are not limited; a mat you make, by its own mats)
            for _, e in ipairs(q.mats) do
              if e.sub then
                for _, m in ipairs(quote(e.sub, 1).mats) do
                  if not m.vendor then crafts = min(crafts, floor(listedOf(m.id) / (e.n / e.sub.count * m.n))) end
                end
              elseif not e.vendor then
                crafts = min(crafts, floor(listedOf(e.id) / e.n))
              end
            end
            -- the mats of many crafts are not all at the one cheapest listing: costed at AH value
            -- when that is dearer, and the profit is the smallest one (as the tooltips show it)
            local unitCost = max(q.cost.lo, q.cost.mkt or 0)
            local fitCrafts, limited = crafts, false
            if gold then
              local can = floor(gold / unitCost)
              if can < crafts then fitCrafts, limited = can, true end
            end
            if crafts >= 1 and fitCrafts >= 1 then
              local whole = max(1, floor(crafts * r.count))
              local n = max(1, floor(fitCrafts * r.count))
              -- units = n: the crafts your gold does not pay for are never listed ahead of yours
              local f = { id = r.product, kind = "craft", buyMax = math.ceil(unitCost / r.count), units = n,
                          cost = fitCrafts * unitCost, relist = q.sellUnit.lo, usual = 0 }
              local fit = { units = n, cost = fitCrafts * unitCost, profit = fitCrafts * q.shown,
                            limited = limited, gold = gold, whole = whole }
              local okD, dv = pcall(dayValue, f, fit)
              if okD and type(dv) == "table" and (tonumber(dv.dayProfit) or 0) > 0 then
                local main
                for _, e in ipairs(q.mats) do
                  if not e.vendor and not e.sub and not main then main = e end
                end
                main = main or q.mats[1]
                out[#out + 1] = { id = r.product, kind = "craft", craft = true, recipe = r.id, r = r, q = q,
                  crafts = fitCrafts, wholeCrafts = crafts, units = n, cost = fit.cost, profit = fit.profit, fit = fit,
                  dayProfit = dv.dayProfit, dayValue = dv.dayValue, day = dv.day, rate = dv.rate,
                  countAt = dv.countAt, searchID = main and main.id or r.product }
              end
            end
          end
        end
      end
    end
  end
  tsort(out, function(a, b)
    if a.dayProfit ~= b.dayProfit then return a.dayProfit > b.dayProfit end
    return a.recipe < b.recipe
  end)
  -- one idea per item made
  local seen, list = {}, {}
  for _, x in ipairs(out) do
    if not seen[x.id] then
      seen[x.id] = true
      list[#list + 1] = x
    end
  end
  for _, x in ipairs(list) do
    local r, q = x.r, x.q
    local single = #r.mats == 1
    local verb = r.skill == SMELTING and "Smelt " or "Make "
    -- "Smelt 20 Thorium Ore", "Make 50: 200 Solid Stone", "Make 40, mats 3g 12s"
    if single and r.skill == SMELTING then
      x.subText = paint(verb .. count(x.crafts * r.mats[1].n) .. " " .. nameOf(r.mats[1].id), "buy")
    elseif single then
      x.subText = paint(verb .. count(x.units) .. ": " .. count(x.crafts * r.mats[1].n) .. " " .. nameOf(r.mats[1].id), "buy")
    else
      x.subText = paint(verb .. count(x.units) .. ", mats " .. shortMoney(x.cost), "buy")
    end
    x.sub2Text = paint("Sell " .. shortMoney(x.countAt or q.sellUnit.lo) .. " each", "sell")
    x.noteText = (x.rate or 0) >= 1 and ("~" .. count(x.rate) .. "/day") or "<1/day"
    local what
    if single and r.skill == SMELTING then
      what = count(x.crafts * r.mats[1].n) .. " " .. nameOf(r.mats[1].id)
    elseif single then
      what = count(x.units) .. " from " .. count(x.crafts * r.mats[1].n) .. " " .. nameOf(r.mats[1].id)
    else
      what = count(x.units) .. " from mats costing " .. moneyText(x.cost)
    end
    x.line = nameOf(x.id) .. ": " .. slower(verb) .. what .. ", sell at " .. moneyText(x.countAt or q.sellUnit.lo)
      .. ", +" .. moneyText(x.dayProfit) .. " in a day (your recipe)"
  end
  return list
end
C.Ideas = function(gold)
  local ok, r = pcall(craftIdeas, gold)
  if not ok then
    C.lastError = r
    return {}
  end
  return r
end

-- The hover of a craft idea's row (Sidebar.lua's RowTooltip calls this).
function ns.CraftRowTooltip(tt, x)
  local ok, err = pcall(function()
    local r, q = x.r, x.q
    local gold = { 0.898, 0.722, 0.259 }
    tt:AddLine(paint("Craft idea from your recipes", "buy"))
    tt:AddLine((r.skill == SMELTING and "Smelt " or "Make ") .. count(x.units) .. " " .. nameOf(r.product)
      .. ": buy the mats, then sell what you make.", 0.8, 0.8, 0.8, true)
    tt:AddLine(matsText(q, true, true), 0.6, 0.6, 0.6, true)
    tt:AddDoubleLine("Mats for " .. count(x.crafts) .. (x.crafts == 1 and " craft" or " crafts"), moneyText(x.cost), 0.8, 0.8, 0.8, 1, 1, 1)
    tt:AddDoubleLine("Relist at (each)", moneyText(x.countAt or q.sellUnit.lo), 0.8, 0.8, 0.8, 1, 1, 1)
    local fit = x.fit
    if type(fit) == "table" and fit.limited then
      tt:AddLine("With your gold (" .. moneyText(fit.gold or 0) .. "): " .. count(x.crafts) .. " of "
        .. count(x.wholeCrafts) .. " crafts", gold[1], gold[2], gold[3], true)
    end
    tt:AddDoubleLine("Profit in a day, after the 5% cut", paint("+" .. moneyText(x.dayProfit), "pos"), 0.8, 0.8, 0.8)
    tt:AddLine("It pays at the cheapest prices, at AH value and at the 7-day averages.", 0.6, 0.6, 0.6, true)
  end)
  if not ok then C.lastError = err end
end

local baseFlipIdeas = ns.FlipIdeas
if type(baseFlipIdeas) == "function" then
  -- The sidebar's ideas with at most one from your recipes (two in the 10 of /gl flips),
  -- in its place by what it makes in a day. Nothing changes without a known recipe that pays.
  function ns.FlipIdeas(limit, gold)
    local out, why = baseFlipIdeas(limit, gold)
    if not isOn() then return out, why end
    local crafts = C.Ideas(gold)
    if #crafts == 0 then return out, why end
    limit = limit or 5
    local keep = max(1, floor(limit / 5))
    local res, seen = {}, {}
    for i, x in ipairs(out) do
      res[i] = x
      seen[x.id] = true
    end
    local value = function(x) return tonumber(x.dayProfit) or (type(x.fit) == "table" and tonumber(x.fit.profit)) or tonumber(x.profit) or 0 end
    local added = 0
    for _, c in ipairs(crafts) do
      if added >= keep then break end
      if not seen[c.id] then
        seen[c.id] = true
        added = added + 1
        local at = #res + 1
        for i, x in ipairs(res) do
          if not x.craft and value(x) < c.dayProfit then
            at = i
            break
          end
        end
        tinsert(res, at, c)
      end
    end
    while #res > limit do
      local drop
      for i = #res, 1, -1 do
        if not res[i].craft and not res[i].solid then
          drop = i
          break
        end
      end
      if not drop then
        for i = #res, 1, -1 do
          if not res[i].craft then
            drop = i
            break
          end
        end
      end
      table.remove(res, drop or #res)
    end
    if #res > 0 then return res end
    return out, why
  end
end

---------------------------------------------------------------------------
-- An empty auction house search (the AH code calls ns.EmptySearchLines)
---------------------------------------------------------------------------
local nameIndex, nameByID
-- "Plans: Officer's Boots" -> "plans officers boots" (so "officers boots" finds it too)
local function norm(s)
  return (sgsub(sgsub(sgsub(slower(s or ""), "'", ""), "[^%w]+", " "), "^%s*(.-)%s*$", "%1"))
end

-- Every recipe item and crafted item by name (shortest first), and by id.
local function names()
  if nameIndex then return nameIndex end
  local idx, list, byID = getIndex(), {}, {}
  local function add(id, kind)
    local n = N[id]
    if n then
      local e = { id = id, kind = kind, name = n, key = norm(n) }
      list[#list + 1] = e
      byID[id] = e
    end
  end
  for id in pairs(idx.byItem) do add(id, "recipe") end
  for id in pairs(idx.byProduct) do
    if not idx.byItem[id] then add(id, "product") end
  end
  tsort(list, function(a, b)
    if #a.key ~= #b.key then return #a.key < #b.key end
    return a.id < b.id
  end)
  nameIndex, nameByID = list, byID
  return list
end

local function firstRecipe(list)
  for _, sp in ipairs(list or {}) do
    local r = getRecipe(sp)
    if visible(r) then return r end
  end
  return nil
end

-- The recipe a line is about: a recipe item's (the first one for your faction), a crafted
-- item's only when you know it or may know it (productRecipe). nil: no line for it.
local function entryRecipe(e)
  if e.kind == "recipe" then return firstRecipe(getIndex().byItem[e.id]) end
  return (productRecipe(e.id, nil))
end

-- "Mats: 4 Steel Bar, 4 Heavy Grinding Stone, 4 Jade = 1g 18s": with 4 or more, the 2 dearest
-- priced ones and "+4 others"; a mat you make yourself "(from 1 Copper Ore)" (the total counts
-- it so). Some mats unpriced: the priced ones and how many are left out, "= 777g + 1 with no
-- price" (not "at least 40c" for a vial when the herbs have no price); none priced: no total
-- (never "0c"). Stale prices (ns.AgeState): the total is grey.
local function searchMats(q)
  local list, keep = q.mats, dearest(q.mats, true)
  local total = q.missing == 0 and q.cost.lo or q.partial
  total = total and roundCopper(total) or 0
  local parts = {}
  for i, e in ipairs(list) do
    if not keep or keep[i] then
      parts[#parts + 1] = e.n .. " " .. nameOf(e.id) .. (e.sub and fromText(e) or "")
    end
  end
  if keep then parts[#parts + 1] = "+" .. (#list - MATS_SHOWN) .. " others" end
  local t = "Mats: " .. tconcat(parts, ", ")
  if total > 0 then
    local sum = moneyText(total)
    if q.missing > 0 then sum = sum .. " + " .. q.missing .. " with no price" end
    t = t .. " = " .. (stale() and paint(sum, "muted") or sum)
  end
  return t
end

-- What making it takes, for the item the AH code's lines are about (they already say whether
-- it is listed or binds on pickup): "Makes Officer's Boots. Mats: ...", or for a crafted item
-- "You can make it. Mats: ..." ("You can make it (5 a craft). ..."). bop: the item binds on
-- pickup and those lines could not say so (the game has not loaded that name): "Bind on
-- pickup. Makes ...".
local function entryBop(e, r)
  if e.kind == "recipe" then return RI[e.id] == "B" end
  return r.bop == true
end

-- "make it (5 a craft). Mats: ...", for "You can ..." / "Iron Bar - you can ...".
local function makeItText(r)
  local n = countPrefix(r)
  return "make it" .. (n ~= "" and (" (" .. n .. "a craft)") or "") .. ". " .. searchMats(quote(r))
end

local function aboutLine(e, r, bop)
  local lead = bop and entryBop(e, r) and "Bind on pickup. " or ""
  if e.kind == "recipe" then
    return lead .. "Makes " .. countPrefix(r) .. nameOf(r.product) .. ". " .. searchMats(quote(r))
  end
  return lead .. "You can " .. makeItText(r)
end

-- Another match, by name: "Plans: Officer's Belt (bind on pickup) - Mats: ...", "Iron Bar -
-- you can make it. Mats: ...". What a recipe item makes only when its name does not say it
-- ("Recipe: Transmute Arcanite - makes Arcanite Bar. Mats: ...").
local function namedLine(e, r)
  local name = nameOf(e.id) .. (entryBop(e, r) and " (bind on pickup)" or "")
  if e.kind == "product" then return name .. " - you can " .. makeItText(r) end
  local prod, n = nameOf(r.product), countPrefix(r)
  local makes = ""
  if n ~= "" or slower(nameOf(e.id)):sub(-#prod) ~= slower(prod) then makes = "makes " .. n .. prod .. ". " end
  return name .. " - " .. makes .. searchMats(quote(r))
end

-- The game knows an item by that name (only items it has loaded): true and its id.
local function gameKnows(text)
  local CI = _G.C_Item
  for _, f in ipairs({ type(CI) == "table" and CI.GetItemInfo or false, _G.GetItemInfo or false }) do
    if type(f) == "function" then
      local ok, name, link = pcall(f, text)
      if ok and type(name) == "string" and not isSecret(name) then
        local id = type(link) == "string" and not isSecret(link) and tonumber(smatch(link, "item:(%d+)")) or nil
        return true, id
      end
    end
  end
  return false
end

-- A search for recipe items: a word of it starts Plans, Pattern, Recipe ... (4 letters or more).
local RECIPE_WORDS = { "plans", "pattern", "recipe", "schematic", "formula", "blueprint", "manual" }
local function recipeSearch(words)
  for _, w in ipairs(words) do
    if #w >= 4 then
      for _, k in ipairs(RECIPE_WORDS) do
        if sfind(k, w, 1, true) == 1 then return true end
      end
    end
  end
  return false
end

-- The lines under the AH code's own for a search that found nothing (itemID: the priced item
-- its lines are about, or nil when it found none), 2 entries at most, one per recipe:
--   - that item, or else the one the game knows by the text, when it is a recipe item or
--     something you can make (aboutLine), first when its name is the text;
--   - a recipe item or a crafted item you can make that the text names exactly: by name
--     (namedLine), or as above when the AH code's lines are about the text and none came first;
--   - the AH code's item when its name is not the text (it found it by the words), only when
--     the text names nothing with a line ("pattern: black slippers" is not its best match,
--     Pattern: Black Whelp Slippers);
--   - a bind-on-pickup item the text names that you cannot make (never on the AH): the recipe
--     items that make it, by name ("officer's boots": Plans: Officer's Boots);
--   - only when the AH code found no priced item, the game knows no item by the text and no
--     name is the text: the recipe items and the items you can make with a word starting with
--     each word of it, by name, and for a recipe search ("plans officer") "6 more match: type
--     more of the name."
-- Two items of one name that make items of one name (an older version of it): the first only.
-- Nothing for an item that is not listed and is neither (Linen Cloth, Iron Ore), nor for
-- other items that only share its words. Not at another market (its prices are not these).
local SEARCH_SHOWN = 2
local function emptySearch(text, itemID)
  if not isOn() or not hasData() or mismatch() or type(text) ~= "string" or isSecret(text) then return nil end
  local key = norm(text)
  if #key < 3 then return nil end
  names()
  -- The AH code's lines are about its priced item, else about the text (the item the game knows by it).
  local subject = plain(itemID)
  if subject and type(ns.BaseItemID) == "function" then subject = ns.BaseItemID(subject) or subject end
  local priced, known = subject ~= nil, subject ~= nil
  if not priced then known, subject = gameKnows(text) end
  local out, used, seen, count = {}, {}, {}, 0
  local function add(e, about)
    local r = entryRecipe(e)
    if not r or used[r.id] then return end
    local same = e.key .. "|" .. norm(nameOf(r.product))
    if seen[same] then return end
    used[r.id], seen[same] = true, true
    count = count + 1
    if count <= SEARCH_SHOWN then out[#out + 1] = about and aboutLine(e, r, not known) or namedLine(e, r) end
  end
  local e = subject and nameByID[subject]
  local exact = {}
  for _, x in ipairs(nameIndex) do
    if #x.key > #key then break end
    if x.key == key and x ~= e then exact[#exact + 1] = x end
  end
  local named = e and e.key == key
  if named then add(e, true) end
  for _, x in ipairs(exact) do add(x, not priced and count == 0) end
  if e and not named and count == 0 then add(e, true) end
  if count == 0 then
    -- a bind-on-pickup item you cannot make: its recipe items
    for i = named and 0 or 1, #exact do
      local x = i == 0 and e or exact[i]
      for _, sp in ipairs(x.kind == "product" and getIndex().byProduct[x.id] or {}) do
        local r = getRecipe(sp)
        if visible(r) and r.bop then
          for _, it in ipairs(r.items) do
            local y = nameByID[it]
            if y and y.kind == "recipe" then add(y, false) end
          end
        end
      end
    end
  end
  if known or #exact > 0 then return #out > 0 and out or nil end
  -- Every word of the text starts a word of the name ("plans officer": Plans: Officer's
  -- Boots), not only inside one (Copper Ore is not Copper Claymore).
  local words = {}
  for w in sgmatch(key, "%S+") do words[#words + 1] = w end
  for _, x in ipairs(nameIndex) do
    local all = true
    for _, w in ipairs(words) do
      if sfind(x.key, w, 1, true) ~= 1 and not sfind(x.key, " " .. w, 1, true) then
        all = false
        break
      end
    end
    if all then add(x, false) end
  end
  if count > SEARCH_SHOWN and recipeSearch(words) then
    out[#out + 1] = (count - SEARCH_SHOWN) .. " more match: type more of the name."
  end
  return #out > 0 and out or nil
end
C.EmptySearch = emptySearch

ns.EmptySearchLines = ns.EmptySearchLines or {}
tinsert(ns.EmptySearchLines, function(text, itemID)
  local ok, r = pcall(emptySearch, text, itemID)
  if not ok then
    C.lastError = r
    return nil
  end
  return r
end)

---------------------------------------------------------------------------
-- /gl crafts
---------------------------------------------------------------------------
local HELP = "/gl crafts : craft and smelt profit on recipe, mat and crafted item tooltips and in the Professions window (on, off or status)"
C.HELP = HELP

local function statusLines()
  local out = {}
  out[1] = "craft tips are " .. (isOn() and "on" or "off") .. (isOn() and " (/gl crafts off turns them off)." or " (/gl crafts on turns them back on).")
  local st = store()
  local idx = getIndex()
  local any, mining = false, false
  local ids = {}
  for sk in pairs(PROF_NAME) do ids[#ids + 1] = sk end
  tsort(ids)
  for _, sk in ipairs(ids) do
    local rank = skillRank(sk)
    if rank > 0 then
      any = true
      if sk == SMELTING then mining = true end
      local known, maybe = 0, 0
      for _, sp in ipairs(idx.bySkill[sk] or {}) do
        local s = knownState(getRecipe(sp))
        if s == "known" then known = known + 1 elseif s == "maybe" then maybe = maybe + 1 end
      end
      local line = "  " .. PROF_NAME[sk] .. " " .. rank .. ": " .. known .. " known recipes"
      if not st.scanned[sk] then
        line = line .. ", " .. maybe .. " more it may know (open its window once to be sure)"
      end
      out[#out + 1] = line
    end
  end
  if not any then out[#out + 1] = "  no crafting professions found on this character." end
  if not mining then out[#out + 1] = "  Smelting is Mining: ore tips need Mining (Blacksmithing alone does not smelt)." end
  return out
end
C.StatusLines = statusLines

local function craftsCommand(rest)
  local S = settings()
  if rest == "on" then
    S.crafts = nil
    invalidate()
    say("craft tips are on.")
    C.RefreshProfessions()
  elseif rest == "off" then
    S.crafts = false
    invalidate()
    say("craft tips are off. /gl crafts on turns them back on.")
    C.RefreshProfessions()
  elseif rest == "" or rest == "status" then
    for _, l in ipairs(statusLines()) do say(l) end
  else
    say("unknown choice. Use /gl crafts on, off or status.")
  end
end

local baseSlash = ns.HandleSlash
function ns.HandleSlash(msg)
  local m = type(msg) == "string" and msg or ""
  local cmd, rest = smatch(m, "^%s*(%S*)%s*(.-)%s*$")
  cmd = slower(cmd or "")
  if cmd == "crafts" or cmd == "craft" then
    local ok, err = pcall(craftsCommand, slower(rest or ""))
    if not ok then
      C.lastError = err
      say("craft tips: " .. tostring(err))
    end
    return
  end
  if type(baseSlash) == "function" then baseSlash(msg) end
  if cmd == "help" or cmd == "?" then say(HELP) end
end

---------------------------------------------------------------------------
-- Events
---------------------------------------------------------------------------
if type(_G.CreateFrame) == "function" then
  local ok, f = pcall(_G.CreateFrame, "Frame")
  if ok and type(f) == "table" then
    for _, ev in ipairs({ "ADDON_LOADED", "PLAYER_LOGIN", "TRADE_SKILL_SHOW", "TRADE_SKILL_LIST_UPDATE",
                          "TRADE_SKILL_DATA_SOURCE_CHANGED", "TRADE_SKILL_CLOSE", "NEW_RECIPE_LEARNED",
                          "LEARNED_SPELL_IN_SKILL_LINE", "SKILL_LINES_CHANGED" }) do
      pcall(f.RegisterEvent, f, ev)   -- an event this client does not have is skipped
    end
    pcall(f.SetScript, f, "OnEvent", function(_, event, a1)
      local okE, err = pcall(function()
        if event == "ADDON_LOADED" then
          if a1 == "Blizzard_Professions" then C.AttachProfessions() end
        elseif event == "PLAYER_LOGIN" then
          store()
          C.AttachProfessions()
        elseif event == "TRADE_SKILL_SHOW" or event == "TRADE_SKILL_LIST_UPDATE" or event == "TRADE_SKILL_DATA_SOURCE_CHANGED" then
          C.AttachProfessions()
          scanSoon()
          C.RefreshProfessions()
        elseif event == "NEW_RECIPE_LEARNED" or event == "LEARNED_SPELL_IN_SKILL_LINE" then
          learned(a1)
          C.RefreshProfessions()
        elseif event == "SKILL_LINES_CHANGED" then
          -- Enchants.lua reads the ranks again on this event; a moment later a profession
          -- that is gone (rank 0) has its recipes forgotten.
          invalidate()
          dropSoon()
        end
      end)
      if not okE then C.lastError = err end
    end)
  end
end
